    return (data ?? []).map((row) => ({
      edgeId: row.edge_id,
      fromThreadId: row.from_thread_id,
      toThreadId: row.to_thread_id,
      kind: row.kind,
      createdAt: row.created_at,
      metadata: row.metadata ?? {},
    })) as PantavionContinuityEdge[];
  }

